BEGIN;
INSERT INTO rotamapa_private.qa_operators(user_id) VALUES('00000000-0000-4000-8000-000000000001') ON CONFLICT DO NOTHING;
INSERT INTO public.rotamapa_portfolios(user_id,id,name) VALUES('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000778','Reset fixture');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
SELECT set_config('request.jwt.claims','{"is_anonymous":false}',false);
SELECT set_config('request.headers','{"x-rotamapa-portfolio":"00000000-0000-4000-8000-000000000778"}',false);
SET ROLE authenticated;
INSERT INTO public.rotamapa_commerce_items(user_id,portfolio_id,id,kind,data) VALUES(auth.uid(),public.rotamapa_current_portfolio(),'99000000-0000-4000-8000-000000000010','product','{"id":"99000000-0000-4000-8000-000000000010","kind":"product","name":"Synthetic reset product","priceCents":1000}');
INSERT INTO public.rotamapa_commerce_items(user_id,portfolio_id,id,kind,data) SELECT auth.uid(),public.rotamapa_current_portfolio(),id::uuid,'sale',jsonb_build_object('id',id,'kind','sale','clientId','synthetic','clientName','Synthetic','date',day,'status','confirmed','totalCents',1000,'lines',jsonb_build_array(jsonb_build_object('productId','99000000-0000-4000-8000-000000000010','name','Synthetic reset product','quantity',1,'tableUnitCents',1000,'unitCents',1000,'discountBps',0,'minQty',0,'label','Preço de tabela','totalCents',1000,'campaign',null))) FROM (VALUES('99000000-0000-4000-8000-000000000011','2026-10-10'),('99000000-0000-4000-8000-000000000012','2026-11-10')) x(id,day);
RESET ROLE;
DO $$DECLARE before_data jsonb;fingerprint text;result jsonb;BEGIN
 SELECT data INTO before_data FROM public.rotamapa_commerce_items WHERE id='99000000-0000-4000-8000-000000000012';
 SELECT md5(string_agg(id::text||':'||revision::text||':'||data::text,E'\n' ORDER BY id)) INTO fingerprint FROM public.rotamapa_commerce_items WHERE id='99000000-0000-4000-8000-000000000012';
 BEGIN PERFORM rotamapa_private.reset_november_2026_sales('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000778',99,fingerprint);RAISE EXCEPTION 'bad CAS allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 result:=rotamapa_private.reset_november_2026_sales('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000778',1,fingerprint);
 PERFORM test.ensure((result->>'removed')::int=1 AND (result->>'backup')::boolean,'exact monthly action');
 PERFORM test.ensure((SELECT backup#>'{sales,0,data}'=before_data FROM public.rotamapa_sales_resets WHERE generation=(result->>'generation')::uuid),'original complete in backup');
 PERFORM test.ensure((SELECT count(*)=1 FROM public.rotamapa_commerce_items WHERE id='99000000-0000-4000-8000-000000000011'),'October preserved');
 PERFORM test.ensure((SELECT count(*)=0 FROM public.rotamapa_commerce_items WHERE id='99000000-0000-4000-8000-000000000012'),'November removed');
END$$;
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_sales_reset_state()->'removedIds') ? '99000000-0000-4000-8000-000000000012','owner gets replay barrier');
DO $$DECLARE old_data jsonb;fresh jsonb;generation text;BEGIN
 SELECT backup#>'{sales,0,data}',r.generation::text INTO old_data,generation FROM public.rotamapa_sales_resets r WHERE portfolio_id=public.rotamapa_current_portfolio();
 BEGIN INSERT INTO public.rotamapa_commerce_items(user_id,portfolio_id,id,kind,data) VALUES(auth.uid(),public.rotamapa_current_portfolio(),'99000000-0000-4000-8000-000000000012','sale',old_data);RAISE EXCEPTION 'stale device resurrected';EXCEPTION WHEN serialization_failure THEN NULL;END;
 fresh:=old_data||jsonb_build_object('id','99000000-0000-4000-8000-000000000013');
 BEGIN INSERT INTO public.rotamapa_commerce_items(user_id,portfolio_id,id,kind,data) VALUES(auth.uid(),public.rotamapa_current_portfolio(),'99000000-0000-4000-8000-000000000013','sale',fresh);RAISE EXCEPTION 'unmarked old client allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 fresh:=fresh||jsonb_build_object('resetGeneration',generation);
 INSERT INTO public.rotamapa_commerce_items(user_id,portfolio_id,id,kind,data) VALUES(auth.uid(),public.rotamapa_current_portfolio(),'99000000-0000-4000-8000-000000000013','sale',fresh);
 BEGIN PERFORM rotamapa_private.reset_november_2026_sales(auth.uid(),public.rotamapa_current_portfolio(),1,'x');RAISE EXCEPTION 'maintenance exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END$$;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
SELECT test.ensure(public.rotamapa_sales_reset_state()='{"generations":{},"removedIds":[]}'::jsonb,'other account isolated');
SELECT test.ensure((SELECT count(*)=0 FROM public.rotamapa_sales_resets),'backup isolated');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
SELECT set_config('request.jwt.claims','{"is_anonymous":true}',false);
SELECT test.ensure((SELECT count(*)=0 FROM public.rotamapa_sales_resets),'anonymous cannot read backup');
RESET ROLE;
ROLLBACK;
SELECT 'Monthly reset backup, October preservation, revision CAS, stale-device block, new generation, private maintenance and isolation passed' AS result;
